import numpy as np


def _affine(x):
    return np.column_stack((np.ones(len(x)), x))


def _fit(x, y):
    return np.linalg.lstsq(x, y, rcond=None)[0]


def run_node(inputs: dict) -> dict:
    study = inputs['__input__']
    calibrated = inputs['node_00']
    panel_b = study['panel_b']
    operator = _fit(_affine(panel_b['u']), panel_b['v'])
    z = _affine(calibrated['x_tr_cal']) @ operator
    z_test = _affine(calibrated['x_te_cal']) @ operator
    train = study['train']
    return {'z_tr': z, 'z_te': z_test, 'y': train['y'], 'traj': train['traj']}

